/**
 * Engine 3: ranked, free-first intervention plan for a set of gaps.
 * Source: workbook sheets "Interventions" (ranked list incl. ANY rows, order-of-operations note A35)
 * and "Gap Calculator" section 4 (C62-C68: plan, add-ons from secondary flags, money, device, re-test rule).
 * Catalogue: /data/catalogues/interventions.json (generated by scripts/engines/export-interventions.py).
 *
 * Rules
 *  - Prerequisite gaps (G1) are planned first, then the rest by hours to close (largest first).
 *  - Each gap gets the three ranked interventions for its primary code (video/app ones dropped when the
 *    device check fails), plus the rank-1 intervention of each secondary flag as an add-on.
 *  - Paid tuition (ANY-1) only when gaps span 2+ chapters AND the free plan has run 3+ weeks without
 *    closing them, or a parent asked for it. Never as a first step.
 *  - Re-test after the planned weeks (minimum 7 days), then a 7-day retention probe.
 */
import type { Gap, GapCode, IsoUtc } from '../types';
import catalogueFile from '../../data/catalogues/interventions.json';
import { DEEP_GAP_SIZE, FLAG_ADD_ON, PAID_TUITION_FREE_PLAN_WEEKS, PAID_TUITION_INR, PAID_TUITION_MIN_CHAPTERS } from './config';
import { addDays, parseInr, ProfileLike, profileGet, round } from './util';

export interface Intervention {
  id: string;
  gapCode: GapCode | 'ANY';
  rank: number;
  name: string;
  whatToDo: string;
  exampleCbseG8Maths: string;
  timeCost: string;
  minutesPerSession: number;
  sessions: number;
  spreadWeeks: number;
  totalMinutes: number;
  effort: 'low' | 'medium' | 'high';
  money: 'free' | 'low' | 'paid';
  inrPerMonth: { min: number; max: number };
  kind: string;
  requiresDevice: boolean;
  alrIndices: string[];
  evidence: string;
  feasibilityParams: string[];
}

export const INTERVENTIONS: Intervention[] = (catalogueFile as { items: Intervention[] }).items;

/** Gap plus the chapter it sits in (needed for the 2+ chapters rule). */
export type PlanGap = Gap & { chapterId?: string };

export interface PlanContext {
  now: IsoUtc;
  /** Overrides for profile lookups. */
  monthlyBudgetInr?: number;
  deviceOk?: boolean;
  weeklyHours?: number;
  /** Weeks the current free plan has already run without closing the gaps. */
  freePlanWeeks?: number;
  parentRequestedTuition?: boolean;
  /** chapterId per subtopicId, used when a gap has no chapterId. */
  chapterOf?: Record<string, string>;
  catalogue?: Intervention[];
}

export interface PlannedStep {
  interventionId: string;
  rank: number;
  name: string;
  whatToDo: string;
  timeCost: string;
  effort: Intervention['effort'];
  money: Intervention['money'];
  inrPerMonth: Intervention['inrPerMonth'];
  totalMinutes: number;
  alrIndices: string[];
  addOnFor?: GapCode;
}

export interface GapPlan {
  gapId: string;
  subtopicId: string;
  chapterId?: string;
  code: GapCode;
  hours: number;
  weeks: number | null;
  steps: PlannedStep[];
  addOns: PlannedStep[];
  addOnText: string;
  moneyCheck: string;
  deviceCheck: string;
  retestRule: string;
  retestDateUtc: IsoUtc;
  retentionProbeDateUtc: IsoUtc;
}

export interface InterventionPlan {
  gaps: GapPlan[];
  paidTuition: { recommended: boolean; reason: string; inrPerMonth: { min: number; max: number }; affordable: boolean };
  optionalApp: PlannedStep | null;
  totalMinutes: number;
  totalInrPerMonth: { min: number; max: number };
  chaptersWithGaps: number;
  orderOfOperations: string;
}

/** Monthly budget from #178 (annual education budget in the 430 file: rupees, text or band) ÷ 12. */
function budgetFrom(profile: ProfileLike | undefined): number {
  const annual = parseInr(profileGet(profile, 'p178'));
  return annual === undefined ? 0 : Math.round(annual / 12);
}

function deviceFrom(profile: ProfileLike | undefined): boolean {
  const v = profileGet(profile, 'p193');
  if (v === undefined) return true;
  if (typeof v === 'boolean') return v;
  return !/^(none|no|n|inadequate|shared_none)$/i.test(String(v));
}

function step(i: Intervention, addOnFor?: GapCode): PlannedStep {
  return {
    interventionId: i.id, rank: i.rank, name: i.name, whatToDo: i.whatToDo, timeCost: i.timeCost, effort: i.effort,
    money: i.money, inrPerMonth: i.inrPerMonth, totalMinutes: i.totalMinutes, alrIndices: i.alrIndices, ...(addOnFor ? { addOnFor } : {}),
  };
}

/** Workbook C66. */
export function moneyCheckText(budgetInr: number, gapSize: number): string {
  if (budgetInr <= 0) return '₹0 plan: all rank-1/2 interventions above are free. Paid tuition is not needed unless gaps span 2+ chapters after 3 weeks.';
  if (gapSize >= DEEP_GAP_SIZE) return 'Budget available and gap is deep: consider 4 weeks of targeted sessions (ANY-1, ₹2,000–6,000) WITH the written gap list; re-test after.';
  return 'Budget available but gap is shallow: free plan first; keep the money for a re-test in 3 weeks.';
}

/** Workbook C67. */
export function deviceCheckText(deviceOk: boolean): string {
  return deviceOk ? 'Video / app options usable.' : 'No device: use the paper wider bank, peer tutor and teacher mini-lessons; skip video/app interventions.';
}

/** Workbook C68. */
export function retestRuleText(weeks: number | null): string {
  const w = weeks === null ? 'planned time' : `${weeks} weeks`;
  return `Re-give the failed items (parallel versions from the wider bank) after the plan, then a 7-day retention probe. Log the attempts → ECV; if the level has not moved by 2 after the planned ${w}, re-diagnose – the gap type was probably wrong (usually G1 hiding under G3).`;
}

export function planInterventions(gaps: PlanGap[], profile: ProfileLike | undefined, ctx: PlanContext): InterventionPlan {
  const cat = ctx.catalogue ?? INTERVENTIONS;
  const budget = ctx.monthlyBudgetInr ?? budgetFrom(profile);
  const deviceOk = ctx.deviceOk ?? deviceFrom(profile);
  const weekly = ctx.weeklyHours ?? (Number(profileGet(profile, 'p31')) || undefined);
  const usable = (i: Intervention) => deviceOk || !i.requiresDevice;
  const forCode = (c: GapCode | 'ANY') => cat.filter((i) => i.gapCode === c && usable(i)).sort((a, b) => a.rank - b.rank);

  const open = gaps.filter((g) => g.status !== 'closed');
  const ordered = [...open].sort((a, b) => Number(b.code === 'G1') - Number(a.code === 'G1') || b.hoursToClose - a.hoursToClose || a.id.localeCompare(b.id));

  const plans: GapPlan[] = ordered.map((g) => {
    const steps = forCode(g.code).map((i) => step(i));
    const addOns = g.secondaryFlags.map((f) => forCode(f)[0]).filter(Boolean).map((i) => step(i, i.gapCode as GapCode));
    const weeks = weekly ? round(g.hoursToClose / weekly) : null;
    const retest = addDays(ctx.now, Math.max(7, Math.ceil((weeks ?? 1) * 7)));
    return {
      gapId: g.id,
      subtopicId: g.subtopicId,
      chapterId: g.chapterId ?? ctx.chapterOf?.[g.subtopicId],
      code: g.code,
      hours: g.hoursToClose,
      weeks,
      steps,
      addOns,
      addOnText: g.secondaryFlags.map((f) => FLAG_ADD_ON[f]).filter(Boolean).join(' '),
      moneyCheck: moneyCheckText(budget, g.size),
      deviceCheck: deviceCheckText(deviceOk),
      retestRule: retestRuleText(weeks),
      retestDateUtc: retest,
      retentionProbeDateUtc: addDays(retest, 7),
    };
  });

  const chapters = new Set(plans.map((p) => p.chapterId ?? p.subtopicId.replace(/-st\d+$/, '')));
  const spans = chapters.size >= PAID_TUITION_MIN_CHAPTERS;
  const failed = (ctx.freePlanWeeks ?? 0) >= PAID_TUITION_FREE_PLAN_WEEKS;
  let recommended = false;
  let reason: string;
  if (ctx.parentRequestedTuition) {
    recommended = true;
    reason = 'Parent asked for tuition: book targeted sessions with the written gap list, not blanket coaching.';
  } else if (spans && failed) {
    recommended = true;
    reason = `Gaps span ${chapters.size} chapters and the free plan has run ${ctx.freePlanWeeks} weeks: targeted tuition (2 × 60 min a week for 4 weeks) with the written gap list, then re-test.`;
  } else if (spans) {
    reason = `Gaps span ${chapters.size} chapters; run the free plan for ${PAID_TUITION_FREE_PLAN_WEEKS} weeks first and re-test before paying.`;
  } else {
    reason = 'Not needed: gaps sit in one chapter and free, high-evidence methods cover them.';
  }
  const tuitionStep = cat.find((i) => i.gapCode === 'ANY' && i.rank === 1);
  const app = deviceOk && budget > 0 ? cat.find((i) => i.gapCode === 'ANY' && i.rank === 2) : undefined;

  const all = plans.flatMap((p) => [...p.steps, ...p.addOns]);
  const totalMinutes = all.reduce((s, x) => s + x.totalMinutes, 0) + (recommended && tuitionStep ? tuitionStep.totalMinutes : 0);
  const inr = { min: 0, max: 0 };
  if (recommended) { inr.min += PAID_TUITION_INR.min; inr.max += PAID_TUITION_INR.max; }

  return {
    gaps: plans,
    paidTuition: { recommended, reason, inrPerMonth: { ...PAID_TUITION_INR }, affordable: budget >= PAID_TUITION_INR.min },
    optionalApp: app ? step(app) : null,
    totalMinutes,
    totalInrPerMonth: inr,
    chaptersWithGaps: chapters.size,
    orderOfOperations: (catalogueFile as { orderOfOperations: string }).orderOfOperations,
  };
}
